/* output_config.format garantiza JSON válido según el schema: ya no hace falta limpiar
   backticks ni rezar por las comillas (el 23/10 un "Futuro" entre comillas dentro de la
   síntesis rompía el JSON.parse). Lo que sí puede pasar: refusal o corte por max_tokens. */
const res = $json;
if (res.stop_reason === 'refusal') throw new Error('La IA rechazó el debrief (' + (((res.stop_details || {}).category) || 'sin categoría') + '). Reformulalo o cargá a mano.');
if (res.stop_reason === 'max_tokens') throw new Error('La respuesta de la IA quedó cortada (max_tokens). Acortá el debrief o avisá.');
const content = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const clean = content.replace(/```json|```/g, '').trim();
let parsed;
try { parsed = JSON.parse(clean); }
catch (e) { throw new Error('La IA no devolvió JSON válido: ' + clean.slice(0, 300)); }
const TAREAS = ['VFX','Color','DG','Motion Graphics','IA','3D/CGI','Retoque','SFX/Mezcla','Online'];
parsed.tareas = (parsed.tareas || []).filter(t => TAREAS.includes(t));
parsed.timeline = (parsed.timeline || []).map(t => ({ fase: t.fase || '', inicio: t.inicio || '', fin: t.fin || '', notas: t.notas || '' }));
for (const k of ['nombre','cliente','agencia','productora','director','sintesis','storyboard_url']) parsed[k] = parsed[k] || '';
return [{ json: parsed }];

const w = $('Webhook').first().json;
const b = w.body;
let texto = '';
if (b && typeof b === 'object') texto = b.debrief_text || b.texto || '';
else if (typeof b === 'string') { try { texto = JSON.parse(b).debrief_text || ''; } catch(e) { texto = b; } }
texto = String(texto || '').trim();
if (!texto) throw new Error('El debrief llegó vacío al workflow. Body recibido: ' + JSON.stringify(b).slice(0, 200));
return [{ json: { texto } }];
